import hashlib
import hmac
import os

# Vulnerability 1: Timing attack - using normal equality operator
def authenticate_user_password(password_input, stored_hash):
    # BAD: Non-constant time comparison
    if password_input == stored_hash:
        return True
    return False

# Vulnerability 2: Using insecure MD5 hash
def hash_password(password):
    # BAD: Using MD5 which is insecure
    return hashlib.md5(password.encode()).hexdigest()

# Vulnerability 3: Predictable token generation
def generate_confirmation_token():
    # BAD: Using predictable value (UUID)
    import uuid
    return str(uuid.uuid4())

# Vulnerability 4: Using weak cryptography
def encrypt_data(data):
    # BAD: Not using proper encryption
    return data

# Vulnerability 5: Hardcoded secret key
SECRET_KEY = "my_hardcoded_secret"

# Function simulating JWT encoding with empty secret
def encode_jwt(payload):
    # BAD: Using empty secret
    import jwt
    return jwt.encode(payload, "", algorithm="none")

# Vulnerability 6: Using weak password hashing
def secure_password_hash(password):
    # BAD: Using old/weak password hashing
    salt = os.urandom(16)
    return hashlib.sha1(password.encode() + salt).hexdigest()

